<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="container page-head"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><p class="eyebrow">Mua sắm</p><h1>Giỏ hàng</h1></div><section class="container section"><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><?php if (empty($items)): ?><div class="empty-state"><h2>Giỏ hàng đang trống</h2><p>Chọn một cuốn sách để bắt đầu.</p><a class="button button-primary" href="/books">Chọn sách</a></div><?php else: ?><form method="post" action="/cart/update"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Sách</th><th>Đơn giá</th><th>Số lượng</th><th>Tạm tính</th><th></th></tr></thead><tbody><?php $total=0; foreach ($items as $item): $book=$item['book']; $quantity=$item['quantity']; $line=(int)$book['price']*$quantity; $total+=$line; ?><tr><td><?= ViewHelper::escape($book['title']) ?></td><td><?= ViewHelper::money((int)$book['price']) ?></td><td><label class="sr-only" for="quantity-<?= (int)$book['id'] ?>">Số lượng <?= ViewHelper::escape($book['title']) ?></label><input id="quantity-<?= (int)$book['id'] ?>" name="quantity[<?= (int)$book['id'] ?>]" type="number" min="0" max="<?= (int)$book['stock_quantity'] ?>" value="<?= $quantity ?>"></td><td><?= ViewHelper::money($line) ?></td><td><button type="submit" name="remove_id" value="<?= (int)$book['id'] ?>">Xóa</button></td></tr><?php endforeach; ?></tbody></table></div><?= Csrf::field() ?><p class="book-price">Tổng: <?= ViewHelper::money($total) ?></p><button class="button" type="submit">Cập nhật giỏ hàng</button><a class="button button-primary" href="/checkout">Tiếp tục thanh toán</a></form><?php endif; ?></section>
